package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;

/** The due figures of claims, and the due-totals of people, at the rates on a sheet. */
@Service
public class Dues {

    private final RateRepository rates;
    private final SheetService sheets;

    public Dues(RateRepository rates, SheetService sheets) {
        this.rates = rates;
        this.sheets = sheets;
    }

    /** The due figure a claim shows and totals: the one fixed when it was settled, or else its
     *  {@link #bindable} figure with the late charge on top while it is overdue; null when there is
     *  none. */
    public BigDecimal figure(String sheetId, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal figure = bindable(sheetId, person, claim);
        return figure == null ? null : figure.add(lateCharge(sheetId, claim, figure));
    }

    /** The figure a claim would have today as an open claim bound by no statement: its live due with
     *  the late charge on top while it is overdue; null when there is none. */
    public BigDecimal openFigure(String sheetId, Person person, Claim claim) {
        BigDecimal figure = due(sheetId, person, claim);
        return figure == null ? null : figure.add(lateCharge(sheetId, claim, figure, true));
    }

    /** The figure a statement binds a claim to: the one its person's last statement bound it to, or
     *  else its live due (a pending claim is not bound by a statement while it is pending); never
     *  the late charge, which keeps following the sheet's today. Null when there is none, or when
     *  the statement bound it to n/a. */
    public BigDecimal bindable(String sheetId, Person person, Claim claim) {
        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
            return claim.getStatedDue();
        }
        return due(sheetId, person, claim);
    }

    /** Whether a statement binds a claim to n/a: its person's last statement bound it to n/a, or
     *  else it has no bound figure and no live due because the rate that would apply to it on its
     *  date (for the person's grade on that date) has ended. */
    public boolean bindsNa(String sheetId, Person person, Claim claim) {
        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
            return claim.isStatedNa();
        }
        return due(sheetId, person, claim) == null
                && rates.endedBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
    }

    /** Whether a claim is bound by its person's last statement now (a pending claim is not). */
    private static boolean bound(Claim claim) {
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    }

    /** The late charge on an open (or pending) claim overdue on the sheet's today (its due-by, fixed when it was
     *  made, before today; a correction has none): the late percent in force on its date of its figure for every full 30 days it is overdue,
     *  rounded to two decimals by the claim's {@link #rounding}; 0.00 when it is not overdue. */
    private BigDecimal lateCharge(String sheetId, Claim claim, BigDecimal figure) {
        return lateCharge(sheetId, claim, figure, claim.getStatus().isOpen());
    }

    /** The late charge on a claim taken as open or not, as {@link #lateCharge(String, Claim, BigDecimal)}. */
    private BigDecimal lateCharge(String sheetId, Claim claim, BigDecimal figure, boolean open) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (!open || claim.isCorrection() || claim.isDeferredOn(sheets.today(sheetId))) {
            return none;
        }
        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId)) / 30;
        if (periods <= 0) {
            return none;
        }
        return figure.multiply(sheets.latePct(sheetId, claim.getDate())).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, rounding(sheetId, claim));
    }

    /** Whether a claim of the person counts in the live totals on the sheet's today: it counts, it is
     *  not deferred on that day, and it is not an open (or pending) claim, unbound by a statement,
     *  dated within one of the person's holds. */
    public static boolean countsLive(Person person, Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isStated() && person.isHeldOn(claim.getDate()));
    }

    /** The claims of a person that count in the live totals on the sheet's today. */
    public static List<Claim> live(Person person, List<Claim> theirs, LocalDate today) {
        return theirs.stream().filter(c -> countsLive(person, c, today)).toList();
    }

    /** A person's due-total: the sum of the figures of their claims that count, at most the sheet's
     *  cap in force on its today; null (n/a) when their grade on the sheet's today has no rate on it and no counting claim
     *  has a figure (one fixed, or a live due at the grade in force on its date). */
    public BigDecimal dueTotal(String sheetId, Person person, List<Claim> theirs) {
        List<BigDecimal> figures = theirs.stream().filter(c -> c.getStatus().counts())
                .map(c -> figure(sheetId, person, c)).filter(d -> d != null).toList();
        LocalDate today = sheets.today(sheetId);
        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
        if (!rated && figures.isEmpty()) {
            return null;
        }
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        BigDecimal cap = sheets.cap(sheetId);
        return cap == null ? sum : sum.min(cap);
    }

    /** A claim's live due at the rate, in force on the claim's date, for the person's grade in force
     *  on that date: amount
     *  times pct divided by 100, rounded to two decimals by the claim's {@link #rounding}, and at least the sheet's
     *  floor in force on the claim's date (a correction has no floor); null when no rate applies on that date. */
    private BigDecimal due(String sheetId, Person person, Claim claim) {
        BigDecimal floor = sheets.floor(sheetId, claim.getDate());
        RoundingMode rounding = rounding(sheetId, claim);
        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
                .map(due -> claim.isCorrection() ? due : due.max(floor))
                .orElse(null);
    }

    /** How a claim's live figures round: half up when the date it rounds by (a correction's is that of
     *  the claim it corrects) is before the sheet's policy date, else half to even. */
    private RoundingMode rounding(String sheetId, Claim claim) {
        return claim.roundsBy().isBefore(sheets.policyDateInForce(sheetId)) ? RoundingMode.HALF_UP
                : RoundingMode.HALF_EVEN;
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.hibernate.annotations.Fetch;
import org.hibernate.annotations.FetchMode;
import org.hibernate.annotations.Generated;

/** A claim a person makes: an amount (two decimals), a date, a note and a status. A claim with a
 *  negative amount is a correction of a settled claim of the same person, named by its number. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The claim's number on its sheet, given when it is opened and kept when voided; null for a
     *  claim never opened. */
    @Column(name = "number")
    private String number;

    /** The due fixed when the claim was settled; null when not settled, or settled with no rate. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** Who opened the claim; null for a claim never opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Whether the person's last statement bound this claim to the due it had then. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The due the last statement bound the claim to; null when unbound, or bound with no rate
     *  (its due then stays live). */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** Whether the last statement bound the claim to n/a: it had no due then because the rate that
     *  would apply to it had ended (its due then does not stay live). */
    @Column(name = "stated_na", nullable = false)
    private boolean statedNa;

    /** The number of the settled claim of the same person this correction corrects; null for a claim
     *  that is not a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The date of the claim this correction corrects, which it rounds by; null for a claim that is
     *  not a correction. */
    @Column(name = "corrected_date")
    private LocalDate correctedDate;

    /** The day the claim is due by: fixed when it is made, from its date and the terms of its
     *  person's grade in force on that date; later changes to the terms or its date leave it. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The day the claim is deferred until (see {@link #isDeferredOn}); null when never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** Where the claim is listed: newest first by this. A new claim takes the next from the
     *  database, and a moved claim takes the next again (see {@link #moveTo}). */
    @Generated
    @Column(name = "listed", insertable = false)
    private Long listed;

    /** The claim's status log, oldest first: a line for each status it has had (see {@link #logStatus}). */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @Fetch(FetchMode.SUBSELECT)
    @JoinColumn(name = "claim_id", nullable = false, updatable = false)
    @OrderBy("id")
    private List<ClaimLog> log = new ArrayList<>();

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate correctedDate, LocalDate dueBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.corrects = corrects;
        this.correctedDate = correctedDate;
        this.dueBy = dueBy;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public Long getListed() {
        return listed;
    }

    /** Move the claim to another person, listed at the place given (after every claim listed so far).
     *  It keeps its number, date and status, but no figure a statement bound it to: it is live
     *  again until its new person's next statement. */
    public void moveTo(Long personId, long listed) {
        this.personId = personId;
        this.listed = listed;
        bind(false, null);
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public LocalDate getCorrectedDate() {
        return correctedDate;
    }

    public void setCorrectedDate(LocalDate correctedDate) {
        this.correctedDate = correctedDate;
    }

    /** The date the claim's figures round by: the date of the claim a correction corrects, or else
     *  its own. */
    public LocalDate roundsBy() {
        return correctedDate != null ? correctedDate : date;
    }

    /** Whether the claim is a correction: its amount is below 0.00. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void deferUntil(LocalDate until) {
        this.deferredUntil = until;
    }

    /** Whether the claim is deferred on the day: it is open and the day is before the one it is
     *  deferred until. A deferred claim counts in no total, is not overdue, cannot be settled and a
     *  statement leaves it unbound; from that day on it is an open claim like any other. */
    public boolean isDeferredOn(LocalDate day) {
        return status == ClaimStatus.OPEN && deferredUntil != null && day.isBefore(deferredUntil);
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    public boolean isStatedNa() {
        return statedNa;
    }

    /** Bind the claim to a due (null: none), or unbind it. */
    public void bind(boolean stated, BigDecimal statedDue) {
        bind(stated, statedDue, false);
    }

    /** Bind the claim to a due (null: none, or n/a when {@code na}), or unbind it. */
    public void bind(boolean stated, BigDecimal statedDue, boolean na) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
        this.statedNa = stated && statedDue == null && na;
    }

    public List<ClaimLog> getLog() {
        return List.copyOf(log);
    }

    /** Log the status the claim has now: changed by the user on the day (the sheet's today), with
     *  its due as computed at that moment (null when it has none). */
    public void logStatus(String user, LocalDate on, BigDecimal due) {
        log.add(new ClaimLog(sheetId, status, user, on, due));
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: it starts as a draft, is opened and then settled; a clerk's settle
 *  above the clerk limit leaves it pending until a steward approves it (settled) or rejects it (open
 *  again); a draft, open or pending claim may be voided. A settled or voided claim cannot change
 *  status. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim at this status may move to {@code to}: a pending claim moves to settled or
     *  back to open only by approval or rejection, which ask for it by {@link #PENDING} itself. */
    public boolean canBecome(ClaimStatus to) {
        return switch (to) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || isOpen();
            case DRAFT -> false;
        };
    }

    /** Whether a claim at this status is open: open, or pending approval of its settle. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim at this status counts toward what its person has claimed. */
    public boolean counts() {
        return isOpen() || this == SETTLED;
    }
}

