    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "by_user", nullable = false)
    private String byUser;

    @Column(name = "on_date", nullable = false)
    private LocalDate on;

    @Column(name = "due", precision = 14, scale = 2)
    private BigDecimal due;

    protected ClaimLog() {
    }

    public ClaimLog(String sheetId, ClaimStatus status, String byUser, LocalDate on, BigDecimal due) {
        this.sheetId = sheetId;
        this.status = status;
        this.byUser = byUser;
        this.on = on;
        this.due = due;
    }

    public Long getId() {
        return id;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getByUser() {
        return byUser;
    }

    public LocalDate getOn() {
        return on;
    }

    public BigDecimal getDue() {
        return due;
    }
}
package net.officefloor.hq.app.claim;

import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/** Changes made to many claims at once; each claim is changed in its own transaction, so one that
 *  is refused leaves the others as they are. */
@Service
public class ClaimBulkService {

    /** How many claims a bulk change made, and how many it refused. */
    public record Outcome(int done, int refused) {
    }

    private final ClaimService claims;
    private final ClaimRepository repository;
    private final PersonRepository people;

    public ClaimBulkService(ClaimService claims, ClaimRepository repository, PersonRepository people) {
        this.claims = claims;
        this.repository = repository;
        this.people = people;
    }

    /** Open each of the claims that can be opened, numbering them in list order (people in the
     *  order they were added, newest claim first within a person); each that cannot is refused and
     *  left as it is, and so is an id that names no claim on the sheet. */
    public Outcome open(String sheetId, String user, Set<Long> claimIds) {
        return change(sheetId, user, claimIds, ClaimStatus.OPEN);
    }

    /** Settle each of the claims that can be settled, in list order, exactly as settling one: a claim
     *  a clerk's limit leaves pending counts as settled; each that cannot is refused and left as it
     *  is, and so is an id that names no claim on the sheet. */
    public Outcome settle(String sheetId, String user, Set<Long> claimIds) {
        return change(sheetId, user, claimIds, ClaimStatus.SETTLED);
    }

    private Outcome change(String sheetId, String user, Set<Long> claimIds, ClaimStatus to) {
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.changeStatus(sheetId, user, claim.getId(), to);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    /** The claims of the ids on the sheet in list order: people in the order they were added, newest
     *  claim first within a person. */
    private List<Claim> inListOrder(String sheetId, Set<Long> claimIds) {
        Map<Long, Integer> rank = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) {
            rank.put(listed.get(i).getId(), i);
        }
        return repository.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(c -> claimIds.contains(c.getId()))
                .sorted(Comparator.comparingInt((Claim c) -> rank.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
                .toList();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The paste box: lines of name,amount,date,note, each adding a draft claim for the named person. */
@Service
public class ClaimPasteService {

    /** The claim form's amount: up to two decimals, a negative one being a correction. */
    private static final Pattern AMOUNT = Pattern.compile("\\s*-?\\d{1,12}(\\.\\d{1,2})?\\s*");

    /** The claim form's longest note. */
    private static final int NOTE_MAX = 500;

    /** One parsed line: the person, the amount, the date (null: the sheet's today) and the note. */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note) {
    }

    private final PersonRepository people;
    private final ClaimService claims;

    public ClaimPasteService(PersonRepository people, ClaimService claims) {
        this.people = people;
        this.claims = claims;
    }

    /** Add a draft claim per line, in order, checking every line first; one change, so when any line
     *  is refused nothing is added and nothing is recorded. Blank lines are skipped; a paste with no
     *  lines is refused. Returns how many claims were added. */
    @Transactional
    public int paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\\R")) {
            n++;
            if (!raw.isBlank()) {
                lines.add(parse(sheetId, n, raw));
            }
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
        }
        for (Line line : lines) {
            claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note());
        }
        return lines.size();
    }

    /** A line of name,amount,date,note: the note may hold commas or be absent, the date may be blank. */
    private Line parse(String sheetId, int n, String raw) {
        String[] fields = raw.split(",", 4);
        if (fields.length < 3) {
            throw refused(n, "expected name,amount,date,note");
        }
        String name = fields[0].trim();
        Person person = name.isEmpty() ? null
                : people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
        if (person == null) {
            throw refused(n, "no one named \"" + name + "\" on this sheet");
        }
        if (!AMOUNT.matcher(fields[1]).matches()) {
            throw refused(n, "the amount must be a number with up to two decimals");
        }
        BigDecimal amount = new BigDecimal(fields[1].trim()).setScale(2);
        LocalDate date;
        try {
            date = fields[2].isBlank() ? null : LocalDate.parse(fields[2].trim());
        } catch (DateTimeParseException e) {
            throw refused(n, "the date must be YYYY-MM-DD");
        }
        String note = fields.length < 4 ? "" : fields[3].trim();
        if (note.length() > NOTE_MAX) {
            throw refused(n, "the note is too long");
        }
        return new Line(person, amount, date, note);
    }

    private static ResponseStatusException refused(int n, String why) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": " + why);
    }
}

