package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The claims people make on a sheet. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final Dues dues;
    private final SheetService sheets;
    private final Rollup rollup;
    private final PeriodRepository periods;
    private final RoleService roles;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, Dues dues, SheetService sheets,
            Rollup rollup, PeriodRepository periods, RoleService roles, Audit audit) {
        this.claims = claims;
        this.people = people;
        this.dues = dues;
        this.sheets = sheets;
        this.rollup = rollup;
        this.periods = periods;
        this.roles = roles;
        this.audit = audit;
    }

    /** The claims on the sheet, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDesc(sheetId);
    }

    /** Add a claim for a person; a date left out takes the sheet's today. Refused when the date falls
     *  inside a closed period, or after the person's retirement day, and when a correction (a negative
     *  amount) does not name a settled claim of the person. */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        return add(sheetId, user, personId, amount, date, note, null);
    }

    /** Add a claim for a person, naming the number of the claim it corrects (only a correction keeps it). */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, on);
        refuseRetired(person(sheetId, personId), on);
        Claim corrected = corrected(sheetId, personId, amount, corrects);
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, personId);
            Claim draft = new Claim(sheetId, personId, amount, on, note,
                    corrected == null ? null : corrected.getNumber(), corrected == null ? null : corrected.getDate(),
                    on.plusDays(sheets.termsFor(sheetId, person.gradeOn(on), on)));
            logStatus(sheetId, user, person, draft);
            Claim claim = claims.saveAndFlush(draft);
            audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, claim));
            return claim;
        });
    }

    /** Change a draft claim's amount, date and note; a date left out takes the sheet's today. Refused
     *  when the claim is not a draft (an open claim is changed by voiding it and adding a new one), and
     *  when the claim's date, or the new one, falls inside a closed period, and when the new one is
     *  after the person's retirement day. */
    @Transactional
    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited");
        }
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, on);
        refuseRetired(person(sheetId, claim.getPersonId()), on);
        Claim corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
        return rollup.tracking(sheetId, user, () -> {
            claim.setAmount(amount);
            claim.setCorrects(corrected == null ? null : corrected.getNumber());
            claim.setCorrectedDate(corrected == null ? null : corrected.getDate());
            claim.setDate(on);
            claim.setNote(note);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
            return saved;
        });
    }

    /** Move a claim to a new status; a change its current status does not allow is refused, and so
     *  is settling a claim by the user who opened it, and any change to a claim dated inside a closed
     *  period. A clerk settling a claim whose due is above the sheet's clerk limit leaves it pending
     *  a steward's approval instead. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + to);
        }
        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot settle it");
        }
        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
                ? ClaimStatus.PENDING : to;
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            if (becomes == ClaimStatus.SETTLED) {
                // Settling fixes the due at what it is now, while the claim is still open (the figure a
                // statement bound it to, if any, and its late charge); later changes to rates, the
                // late percent and the sheet's today do not alter it.
                claim.setSettledDue(dues.figure(sheetId, person, claim));
            }
            // A void claim keeps the number it had (never reused).
            claim.setStatus(becomes);
            if (becomes == ClaimStatus.OPEN) {
                claim.setNumber(nextNumber(sheetId, claim.getDate()));
                claim.setOpenedBy(user);
            }
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            String event = switch (becomes) {
                case OPEN -> "CLAIM_OPENED";
                case PENDING -> "CLAIM_PENDING";
                case SETTLED -> "CLAIM_SETTLED";
                case VOID -> "CLAIM_VOIDED";
                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
            };
            String line = record(event, sheetId, user, person, saved);
            if (becomes == ClaimStatus.SETTLED) {
                line += " due=" + dueText(saved.getSettledDue());
            }
            audit.recordOnCommit(line);
            return saved;
        });
    }

    /** Defer an open claim until a day after the sheet's today: until the sheet's today reaches it,
     *  the claim counts in no total, is not overdue, cannot be settled and a statement leaves it
     *  unbound. Refused when the claim's period is closed, the claim is not open, or the day is not
     *  after the sheet's today. */
    @Transactional
    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be deferred");
        }
        if (!until.isAfter(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A claim can only be deferred to a date after the sheet's today");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.deferUntil(until);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved) + " until=" + until);
            return saved;
        });
    }

    /** Approve a pending claim: it becomes settled, its due fixed at the figure it has now (its live
     *  figure and late charge). Refused unless the claim is pending, the user is a steward and is not
     *  the one who opened it, and the claim's period is open. */
    @Transactional
    public Claim approve(String sheetId, String user, long claimId) {
        Claim claim = lockPending(sheetId, user, claimId);
        if (user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot approve it");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.setSettledDue(dues.figure(sheetId, person, claim));
            claim.setStatus(ClaimStatus.SETTLED);
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_APPROVED", sheetId, user, person, saved)
                    + " due=" + dueText(saved.getSettledDue()));
            return saved;
        });
    }

    /** Re-settle a settled claim: its due is fixed again at the figure it would have today as an open
     *  claim bound by no statement (today's rates, grades, floor and late charge). Refused unless the
     *  claim is settled, the user is a steward, and the claim's period is open. */
    @Transactional
    public Claim resettle(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled");
        }
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            BigDecimal old = dues.figure(sheetId, person, claim);
            BigDecimal now = dues.openFigure(sheetId, person, claim);
            claim.setSettledDue(now);
            claim.logStatus(user, sheets.today(sheetId), now);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
                    + " old=" + dueText(old) + " new=" + dueText(now));
            return saved;
        });
    }

    /** Reject a pending claim for a reason: it is open again, bound again by its person's last
     *  statement if that statement included it. Refused unless the claim is pending, the user is a
     *  steward, and the claim's period is open. */
    @Transactional
    public Claim reject(String sheetId, String user, long claimId, String reason) {
        Claim claim = lockPending(sheetId, user, claimId);
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.setStatus(ClaimStatus.OPEN);
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_REJECTED", sheetId, user, person, saved) + " reason=" + reason);
            return saved;
        });
    }

    /** Move a draft, open or pending claim to another person on the sheet. It keeps its number, date
     *  and status, loses any figure a statement bound it to, and is listed as its new person's newest
     *  claim. Refused unless the user is a steward, and when the claim is settled or void, the person
     *  is the one it is already for, the claim's period is closed, or the claim is dated after the
     *  new person's retirement day. */
    @Transactional
    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
        Claim claim = lock(sheetId, claimId);
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can reassign a claim");
        }
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be reassigned");
        }
        if (claim.getPersonId() == toPersonId) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
        }
        refuseClosed(sheetId, claim.getDate());
        Person from = person(sheetId, claim.getPersonId());
        Person to = person(sheetId, toPersonId);
        refuseRetired(to, claim.getDate());
        return rollup.tracking(sheetId, user, () -> {
            claim.moveTo(to.getId(), claims.nextListed());
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
                    + " from=" + from.getName() + " to=" + to.getName());
            return saved;
        });
    }

    /** The pending claim a steward approves or rejects, locked; refused when it is not pending, the
     *  user is not a steward, or its period is closed. */
    private Claim lockPending(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "Only a PENDING claim can be approved or rejected");
        }
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Only a steward can approve or reject a claim");
        }
        return claim;
    }

    /** Log the status the claim has now, changed by the user on the sheet's today, with its due as
     *  computed at this moment. */
    private void logStatus(String sheetId, String user, Person person, Claim claim) {
        claim.logStatus(user, sheets.today(sheetId), dues.figure(sheetId, person, claim));
    }

    private Claim lock(String sheetId, long claimId) {
        return claims.lockByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
    }

    private static String dueText(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2).toPlainString();
    }

    /** The number for a claim of the date opened now: under period numbering, the next in its period
     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet. */
    private String nextNumber(String sheetId, LocalDate date) {
        if (!sheets.periodNumbering(sheetId)) {
            return String.valueOf(sheets.nextClaimNumber(sheetId));
        }
        return periods.findOn(sheetId, date)
                .map(p -> {
                    periods.advanceClaimNumber(p.getId());
                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
                })
                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
    }

    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
     *  or else it is refused. */
    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
        if (amount.signum() >= 0) {
            return null;
        }
        return (corrects == null ? Optional.<Claim>empty()
                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
                        "A negative amount must correct a settled claim of the same person"));
    }

    /** Refuse a change to a claim dated on the day when the day falls inside a closed period. */
    private void refuseClosed(String sheetId, LocalDate day) {
        if (periods.closedOn(sheetId, day)) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
        }
    }

    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
     *  no due (n/a) is within any limit, and a steward settles anything. */
    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
        BigDecimal limit = sheets.clerkLimit(sheetId);
        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            return false;
        }
        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
        return due != null && due.compareTo(limit) > 0;
    }

    /** Refuse a claim of the person dated after the day they are retired from. */
    private static void refuseRetired(Person person, LocalDate day) {
        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "A claim cannot be dated after the person's retirement");
        }
    }

    private Person person(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
    }

    /** An audit record about a claim; one that has a number carries it at the end. */
    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
        String number = claim.getNumber();
        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number != null ? " number=" + number : "");
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A line of a claim's status log: a status it came to have, who made the change, the sheet's today
 *  then, and the claim's due as computed at that moment (null when it had none). */
@Entity
@Table(name = "claim_log")
public class ClaimLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "by_user", nullable = false)
    private String byUser;

    @Column(name = "on_date", nullable = false)
    private LocalDate on;

    @Column(name = "due", precision = 14, scale = 2)
    private BigDecimal due;

    protected ClaimLog() {
    }

    public ClaimLog(String sheetId, ClaimStatus status, String byUser, LocalDate on, BigDecimal due) {
        this.sheetId = sheetId;
        this.status = status;
        this.byUser = byUser;
        this.on = on;
        this.due = due;
    }

    public Long getId() {
        return id;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getByUser() {
        return byUser;
    }

    public LocalDate getOn() {
        return on;
    }

    public BigDecimal getDue() {
        return due;
    }
}
package net.officefloor.hq.app.claim;

import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/** Changes made to many claims at once; each claim is changed in its own transaction, so one that
 *  is refused leaves the others as they are. */
@Service
public class ClaimBulkService {

    /** How many claims a bulk change made, and how many it refused. */
    public record Outcome(int done, int refused) {
    }

    private final ClaimService claims;
    private final ClaimRepository repository;
    private final PersonRepository people;

    public ClaimBulkService(ClaimService claims, ClaimRepository repository, PersonRepository people) {
        this.claims = claims;
        this.repository = repository;
        this.people = people;
    }

    /** Open each of the claims that can be opened, numbering them in list order (people in the
     *  order they were added, newest claim first within a person); each that cannot is refused and
     *  left as it is, and so is an id that names no claim on the sheet. */
    public Outcome open(String sheetId, String user, Set<Long> claimIds) {
        return change(sheetId, user, claimIds, ClaimStatus.OPEN);
    }

    /** Settle each of the claims that can be settled, in list order, exactly as settling one: a claim
     *  a clerk's limit leaves pending counts as settled; each that cannot is refused and left as it
     *  is, and so is an id that names no claim on the sheet. */
    public Outcome settle(String sheetId, String user, Set<Long> claimIds) {
        return change(sheetId, user, claimIds, ClaimStatus.SETTLED);
    }

    private Outcome change(String sheetId, String user, Set<Long> claimIds, ClaimStatus to) {
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.changeStatus(sheetId, user, claim.getId(), to);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    /** The claims of the ids on the sheet in list order: people in the order they were added, newest
     *  claim first within a person. */
    private List<Claim> inListOrder(String sheetId, Set<Long> claimIds) {
        Map<Long, Integer> rank = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) {
            rank.put(listed.get(i).getId(), i);
        }
        return repository.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(c -> claimIds.contains(c.getId()))
                .sorted(Comparator.comparingInt((Claim c) -> rank.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
                .toList();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The paste box: lines of name,amount,date,note, each adding a draft claim for the named person. */
@Service
public class ClaimPasteService {

    /** The claim form's amount: up to two decimals, a negative one being a correction. */
    private static final Pattern AMOUNT = Pattern.compile("\\s*-?\\d{1,12}(\\.\\d{1,2})?\\s*");

    /** The claim form's longest note. */
    private static final int NOTE_MAX = 500;

    /** One parsed line: the person, the amount, the date (null: the sheet's today) and the note. */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note) {
    }

    private final PersonRepository people;
    private final ClaimService claims;

    public ClaimPasteService(PersonRepository people, ClaimService claims) {
        this.people = people;
        this.claims = claims;
    }

    /** Add a draft claim per line, in order, checking every line first; one change, so when any line
     *  is refused nothing is added and nothing is recorded. Blank lines are skipped; a paste with no
     *  lines is refused. Returns how many claims were added. */
    @Transactional
    public int paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\\R")) {
            n++;
            if (!raw.isBlank()) {
                lines.add(parse(sheetId, n, raw));
            }
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
        }
        for (Line line : lines) {
            claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note());
        }
        return lines.size();
    }

    /** A line of name,amount,date,note: the note may hold commas or be absent, the date may be blank. */
    private Line parse(String sheetId, int n, String raw) {
        String[] fields = raw.split(",", 4);
        if (fields.length < 3) {
            throw refused(n, "expected name,amount,date,note");
        }
        String name = fields[0].trim();
        Person person = name.isEmpty() ? null
                : people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
        if (person == null) {
            throw refused(n, "no one named \"" + name + "\" on this sheet");
        }
        if (!AMOUNT.matcher(fields[1]).matches()) {
            throw refused(n, "the amount must be a number with up to two decimals");
        }
        BigDecimal amount = new BigDecimal(fields[1].trim()).setScale(2);
        LocalDate date;
        try {
            date = fields[2].isBlank() ? null : LocalDate.parse(fields[2].trim());
        } catch (DateTimeParseException e) {
            throw refused(n, "the date must be YYYY-MM-DD");
        }
        String note = fields.length < 4 ? "" : fields[3].trim();
        if (note.length() > NOTE_MAX) {
            throw refused(n, "the note is too long");
        }
        return new Line(person, amount, date, note);
    }

    private static ResponseStatusException refused(int n, String why) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": " + why);
    }
}

package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /** What the screen shows of a claim; the amount, and the due fixed when it was settled (null
     *  when there is none), as text with two decimals; who opened it (null when never opened);
     *  whether the last statement bound it, with the due it bound (null when none) and whether it
     *  bound it to n/a; and the number
     *  of the claim it corrects (null when it is not a correction); the date its figures round by
     *  (that of the claim a correction corrects, or else its own); and where it is listed (newest
     *  first by this); and its status log, oldest first; and the day it is deferred until (null when
     *  never deferred). */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, boolean statedNa, String corrects, LocalDate roundsBy, long listed, LocalDate dueBy,
            List<LogLineView> log, LocalDate deferredUntil) {
        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().setScale(2).toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().setScale(2).toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2).toPlainString(),
                    claim.isStatedNa(), claim.getCorrects(), claim.roundsBy(), claim.getListed(), claim.getDueBy(),
                    claim.getLog().stream().map(LogLineView::of).toList(), claim.getDeferredUntil());
        }
    }

    /** A line of a claim's status log: the status, who changed it to that, the sheet's today then, and
     *  the claim's due at that moment as text with two decimals (null when it had none). */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {
        static LogLineView of(ClaimLog line) {
            return new LogLineView(line.getStatus(), line.getByUser(), line.getOn(),
                    line.getDue() == null ? null : line.getDue().setScale(2).toPlainString());
        }
    }

    /** The claim form: a required amount with up to two decimals (a negative one is a correction), an
     *  optional date (the sheet's today when left out), a note that may be empty, and the number of
     *  the settled claim a correction corrects. */
    public record ClaimForm(@NotNull @Pattern(regexp = "\\s*-?\\d{1,12}(\\.\\d{1,2})?\\s*") String amount,
            LocalDate date, @Size(max = 500) String note, @Size(max = 120) String corrects) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }

        String noteValue() {
            return note == null ? "" : note.trim();
        }

        /** The number a correction names (1, 2, ... or P1-1, X-1, ...); null when left blank. */
        String correctsValue() {
            return corrects == null || corrects.isBlank() ? null : corrects.trim();
        }
    }

    /** The claims a bulk action is taken on, by id. */
    public record BulkForm(@NotNull @Size(max = 1000) Set<@NotNull Long> claimIds) {
    }

    /** How many claims a bulk open opened, and how many it refused. */
    public record BulkOpened(int opened, int refused) {
    }

    /** How many claims a bulk settle settled (or left pending a steward's approval), and how many it
     *  refused. */
    public record BulkSettled(int settled, int refused) {
    }

    private final ClaimService service;
    private final ClaimBulkService bulk;

    public ClaimController(ClaimService service, ClaimBulkService bulk) {
        this.service = service;
        this.bulk = bulk;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(ClaimView::of).toList();
    }

    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ClaimForm form) {
        return ClaimView.of(service.add(sheetId.trim(), user.trim(), personId, form.amountValue(), form.date(), form.noteValue(),
                form.correctsValue()));
    }

    @PutMapping("/claims/{claimId}")
    public ClaimView edit(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ClaimForm form) {
        return ClaimView.of(service.edit(sheetId.trim(), user.trim(), claimId, form.amountValue(), form.date(), form.noteValue(),
                form.correctsValue()));
    }

    @PostMapping("/claims/{claimId}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.OPEN));
    }

    @PostMapping("/claims/open")
    public BulkOpened openAll(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkForm form) {
        ClaimBulkService.Outcome outcome = bulk.open(sheetId.trim(), user.trim(), form.claimIds());
        return new BulkOpened(outcome.done(), outcome.refused());
    }

    @PostMapping("/claims/{claimId}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/settle")
    public BulkSettled settleAll(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkForm form) {
        ClaimBulkService.Outcome outcome = bulk.settle(sheetId.trim(), user.trim(), form.claimIds());
        return new BulkSettled(outcome.done(), outcome.refused());
    }

    @PostMapping("/claims/{claimId}/resettle")
    public ClaimView resettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.resettle(sheetId.trim(), user.trim(), claimId));
    }

    /** The day an open claim is deferred until. */
    public record DeferForm(@NotNull LocalDate until) {
    }

    @PostMapping("/claims/{claimId}/defer")
    public ClaimView defer(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody DeferForm form) {
        return ClaimView.of(service.defer(sheetId.trim(), user.trim(), claimId, form.until()));
    }

    /** The reason a steward gives for rejecting a pending claim. */
    public record RejectForm(@NotBlank @Size(max = 500) String reason) {
    }

    @PostMapping("/claims/{claimId}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.approve(sheetId.trim(), user.trim(), claimId));
    }

    @PostMapping("/claims/{claimId}/reject")
    public ClaimView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RejectForm form) {
        return ClaimView.of(service.reject(sheetId.trim(), user.trim(), claimId, form.reason().trim()));
    }

    /** The person a steward moves a claim to. */
    public record ReassignForm(@NotNull Long personId) {
    }

    @PostMapping("/claims/{claimId}/reassign")
    public ClaimView reassign(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ReassignForm form) {
        return ClaimView.of(service.reassign(sheetId.trim(), user.trim(), claimId, form.personId()));
    }

    @PostMapping("/claims/{claimId}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.VOID));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures a sheet rolls up to: what each person has claimed, their due-total and their
 * overdue-total, and the sheet's totals of all three. A change made through {@link #tracking} is followed in the audit by one
 * ROLLUP line per person whose figures it moved (in the order they were added), then a TOTALS line
 * when the sheet's totals moved.
 */
@Service
public class Rollup {

    /** A person's figures as two-decimal text; a due-total of n/a is "n/a". */
    private record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /** The figures of a sheet: each person's by id in the order they were added, and the totals. */
    private record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal,
            String overdueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final Dues dues;
    private final SheetService sheets;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, Dues dues, SheetService sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.dues = dues;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** Make a change on the sheet, then record in the audit, after the change's own records, the
     *  figures it moved. A change that is refused records nothing. */
    @Transactional(propagation = Propagation.MANDATORY)
    public <T> T tracking(String sheetId, String user, Supplier<T> change) {
        Snapshot before = snapshot(sheetId);
        T result = change.get();
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP" + prefix + " person=" + figures.name()
                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
                        + " overdue-total=" + figures.overdueTotal());
            }
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())
                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
        return result;
    }

    private Snapshot snapshot(String sheetId) {
        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
        LocalDate today = sheets.today(sheetId);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> theirs = Dues.live(person, byPerson.getOrDefault(person.getId(), List.of()), today);
            BigDecimal claimed = theirs.stream().map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            BigDecimal due = dues.dueTotal(sheetId, person, theirs);
            BigDecimal overdue = theirs.stream().filter(c -> c.getStatus().isOpen() && c.getDueBy().isBefore(today))
                    .map(c -> dues.figure(sheetId, person, c)).filter(Objects::nonNull)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            overdueTotal = overdueTotal.add(overdue);
            if (due != null) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.getId(), new Figures(person.getName(), text(claimed),
                    due == null ? "n/a" : text(due), text(overdue)));
        }
        return new Snapshot(figures, text(claimedTotal), text(dueTotal), text(overdueTotal));
    }

    private static String text(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A grade a person was given, applying from its from-date (from the beginning of time when it has
 *  none) until a later from-date of the person takes over. */
@Embeddable
public class GradeFrom {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "grade", nullable = false)
    private String grade;

    protected GradeFrom() {
    }

    public GradeFrom(LocalDate fromDate, String grade) {
        this.fromDate = fromDate;
        this.grade = grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getGrade() {
        return grade;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A hold on a person, from its from-date (from the beginning of time when it has none) to its
 *  to-date (open-ended when it has none), both days included. */
@Embeddable
public class Hold {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected Hold() {
    }

    public Hold(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether the hold covers a day. */
    public boolean covers(LocalDate day) {
        return (fromDate == null || !day.isBefore(fromDate)) && (toDate == null || !day.isAfter(toDate));
    }
}
