import java.util.HashMap;
import java.util.Map;

/** A period on a sheet: a named run of days from its from-date to its to-date, both inclusive. A
 *  claim belongs to the period whose days contain its date. A closed period keeps the due-total it
 *  had when it was closed, and no claim dated inside it can be changed. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    /** Each person's due-total for the period, by the person's id, fixed when it was closed; empty
     *  while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    /** The last number given to a claim in the period under period numbering; only ever moved on by
     *  {@link PeriodRepository#advanceClaimNumber}. */
    @Column(name = "last_claim_number", insertable = false, updatable = false)
    private int lastClaimNumber;

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public boolean isClosed() {
        return closed;
    }

    /** The due-total fixed when the period was closed; null while it is open. */
    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    /** Each person's due-total fixed when the period was closed, by the person's id; empty while it
     *  is open. */
    public Map<Long, BigDecimal> getPersonTotals() {
        return Map.copyOf(personTotals);
    }

    /** Close the period, fixing each person's due-total for it at what it is now, and its own
     *  due-total at their sum. */
    public void close(Map<Long, BigDecimal> personTotals) {
        this.closed = true;
        this.personTotals.clear();
        this.personTotals.putAll(personTotals);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.closedTotal = null;
        this.personTotals.clear();
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface PeriodRepository extends JpaRepository<Period, Long> {

    /** The periods on a sheet, earliest first. */
    List<Period> findBySheetIdOrderByFromDateAsc(String sheetId);

    /** Whether the name is in use on the sheet, compared without regard to case. */
    boolean existsBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** Whether a period on the sheet shares a day with the days from one date to another. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.fromDate <= :to and p.toDate >= :from")
    boolean overlaps(String sheetId, LocalDate from, LocalDate to);

    /** Whether the day falls inside a closed period on the sheet. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.closed = true"
            + " and p.fromDate <= :day and p.toDate >= :day")
    boolean closedOn(String sheetId, LocalDate day);

    /** The period on the sheet whose days contain the day, if any. */
    @Query("select p from Period p where p.sheetId = :sheetId and p.fromDate <= :day and p.toDate >= :day")
    Optional<Period> findOn(String sheetId, LocalDate day);

    /** Move the period's last claim number on by one; the row stays locked until the transaction
     *  ends, so two claims opened in it at once get one number each. */
    @Modifying
    @Query("update Period p set p.lastClaimNumber = p.lastClaimNumber + 1 where p.id = :id")
    int advanceClaimNumber(Long id);

    @Query("select p.lastClaimNumber from Period p where p.id = :id")
    int lastClaimNumber(Long id);

    /** A period on a sheet, locked for the rest of the transaction so two closes or reopens of
     *  it happen one after the other. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select p from Period p where p.id = :id and p.sheetId = :sheetId")
    Optional<Period> lockByIdAndSheetId(Long id, String sheetId);
}
