22	/**
23	 * The figures a sheet rolls up to: what each person has claimed, their due-total and their
24	 * overdue-total, and the sheet's totals of all three. A change made through {@link #tracking} is followed in the audit by one
25	 * ROLLUP line per person whose figures it moved (in the order they were added), then a TOTALS line
26	 * when the sheet's totals moved.
27	 */
28	@Service
29	public class Rollup {
30	
31	    /** A person's figures as two-decimal text; a due-total of n/a is "n/a". */
32	    private record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
33	        boolean sameAs(Figures other) {
34	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
35	                    && overdueTotal.equals(other.overdueTotal);
36	        }
37	    }
38	
39	    /** The figures of a sheet: each person's by id in the order they were added, and the totals. */
40	    private record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal,
41	            String overdueTotal) {
42	    }
43	
44	    private final PersonRepository people;
45	    private final ClaimRepository claims;
46	    private final Dues dues;
47	    private final SheetService sheets;
48	    private final Audit audit;
49	
50	    public Rollup(PersonRepository people, ClaimRepository claims, Dues dues, SheetService sheets, Audit audit) {
51	        this.people = people;
52	        this.claims = claims;
53	        this.dues = dues;
54	        this.sheets = sheets;
55	        this.audit = audit;
56	    }
57	
58	    /** Make a change on the sheet, then record in the audit, after the change's own records, the
59	     *  figures it moved. A change that is refused records nothing. */
60	    @Transactional(propagation = Propagation.MANDATORY)
61	    public <T> T tracking(String sheetId, String user, Supplier<T> change) {
62	        Snapshot before = snapshot(sheetId);
63	        T result = change.get();
64	        Snapshot after = snapshot(sheetId);
65	        String prefix = " sheet=" + sheetId + " by=" + user;
66	        after.people().forEach((id, figures) -> {
67	            if (!figures.sameAs(before.people().get(id))) {
68	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + figures.name()
69	                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
70	                        + " overdue-total=" + figures.overdueTotal());
71	            }
72	        });
73	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
74	                || !Objects.equals(before.dueTotal(), after.dueTotal())
75	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
76	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
77	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
78	        }
79	        return result;
80	    }
81	
82	    private Snapshot snapshot(String sheetId) {
83	        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByListedDesc(sheetId).stream()
84	                .collect(Collectors.groupingBy(Claim::getPersonId));
85	        Map<Long, Figures> figures = new LinkedHashMap<>();
86	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
87	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
88	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
89	        LocalDate today = sheets.today(sheetId);
90	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
91	            List<Claim> theirs = Dues.live(person, byPerson.getOrDefault(person.getId(), List.of()), today);
92	            BigDecimal claimed = theirs.stream().map(Claim::getAmount)
93	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
94	            BigDecimal due = dues.dueTotal(sheetId, person, theirs);
95	            BigDecimal overdue = theirs.stream().filter(c -> c.getStatus().isOpen() && c.getDueBy().isBefore(today))
96	                    .map(c -> dues.figure(sheetId, person, c)).filter(Objects::nonNull)
97	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
98	            claimedTotal = claimedTotal.add(claimed);
99	            overdueTotal = overdueTotal.add(overdue);
100	            if (due != null) {
101	                dueTotal = dueTotal.add(due);
102	            }
103	            figures.put(person.getId(), new Figures(person.getName(), text(claimed),
104	                    due == null ? "n/a" : text(due), text(overdue)));
105	        }
106	        return new Snapshot(figures, text(claimedTotal), text(dueTotal), text(overdueTotal));
107	    }
108	
109	    private static String text(BigDecimal value) {
110	        return value.setScale(2).toPlainString();
111	    }
112	}
