102	                .orElseGet(() -> new SettingValue(id, key, on, value));
103	        v.setValue(value);
104	        settingValues.saveAndFlush(v);
105	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value=" + shown
106	                + (from != null ? " from=" + from : ""));
