1	import { HttpClient } from '@angular/common/http';
2	import { Injectable, inject } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { Grade, Hold, Person, heldOn } from './people';
5	import { Rate, atLeast, due, pctOn } from './rates';
6	import { DatedValue, STARTING_FLOOR, STARTING_LATE_PCT, valueOn } from './settings';
7	import { Session } from './session';
8	
9	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk
10	 *  limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
11	 *  DRAFT, OPEN or PENDING claim may be VOID. */
12	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
13	
14	/** A change of status a claim can be asked for. */
15	export type ClaimAction = 'open' | 'settle' | 'resettle' | 'void' | 'approve' | 'reject';
16	
17	/** Whether a claim is open: OPEN, or PENDING approval of its settle. */
18	export function isOpen(c: Claim): boolean {
19	  return c.status === 'OPEN' || c.status === 'PENDING';
20	}
21	
22	/** Whether a claim at this status counts toward claimed, due-total and every total. */
23	export function counts(c: Claim): boolean {
24	  return isOpen(c) || c.status === 'SETTLED';
25	}
26	
27	/** Whether a claim is deferred on the sheet's today: it is OPEN and today is before the day it is
28	 *  deferred until. Until then it counts in no total, is not overdue and cannot be settled. */
29	export function deferred(c: Claim, today: string | null): boolean {
30	  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
31	}
32	
33	/** Whether a claim counts in the live totals on the sheet's today: it counts, it is not deferred,
34	 *  and it is not an open (or pending) claim, unbound by a statement, dated within one of its
35	 *  person's holds. */
36	export function countsLive(c: Claim, holds: Hold[], today: string | null): boolean {
37	  return counts(c) && !deferred(c, today) && !(isOpen(c) && !c.stated && heldOn(holds, c.date));
38	}
39	
40	export interface Claim {
41	  id: number;
42	  personId: number;
43	  /** The amount as text with two decimals. */
44	  amount: string;
45	  date: string;
46	  note: string;
47	  status: ClaimStatus;
48	  /** The claim's number on the sheet, given when it is opened (1, 2, ... or, under period numbering,
49	   *  <period name>-<n>, or X-<n> for a claim in no period); null for a claim never opened. */
50	  number: string | null;
51	  /** The due fixed when the claim was settled, as text with two decimals; null when it is not
52	   *  settled, or was settled while its person's grade had no rate (its due then stays live). */
53	  settledDue: string | null;
54	  /** Who opened the claim; null when it was never opened. That user cannot settle it. */
55	  openedBy: string | null;
56	  /** Whether its person's last statement bound it to the due it had then. */
57	  stated: boolean;
58	  /** The due the last statement bound it to, as text with two decimals; null when it is unbound,
59	   *  or was bound while it had no due (its due then stays live). */
60	  statedDue: string | null;
61	  /** Whether the last statement bound it to n/a: the rate that would apply to it had ended (its
62	   *  due then does not stay live). */
63	  statedNa: boolean;
64	  /** The number of the settled claim this correction corrects; null when it is not a correction. */
65	  corrects: string | null;
66	  /** The date (yyyy-mm-dd) its figures round by: that of the claim a correction corrects, or else
67	   *  its own. */
68	  roundsBy: string;
69	  /** Where the claim is listed: claims are listed newest first by this (a claim moved to another
70	   *  person is listed as that person's newest). */
71	  listed: number;
72	  /** The day (yyyy-mm-dd) it is due by: fixed when it was made, from its date and the terms of its
73	   *  person's grade in force on that date. */
74	  dueBy: string;
75	  /** Its status log, oldest first: a line for each status it has had. */
76	  log: ClaimLogLine[];
77	  /** The day (yyyy-mm-dd) it is deferred until; null when it was never deferred. */
78	  deferredUntil: string | null;
79	}
80	
81	/** A line of a claim's status log: the status, who changed it to that, the sheet's today then
82	 *  (yyyy-mm-dd), and the claim's due at that moment as text with two decimals (null when it had
83	 *  none). */
84	export interface ClaimLogLine {
85	  status: ClaimStatus;
86	  by: string;
87	  on: string;
88	  due: string | null;
89	}
90	
91	export interface ClaimForm {
92	  amount: string;
93	  /** yyyy-mm-dd, or null for the sheet's today. */
94	  date: string | null;
95	  note: string;
96	  /** The number of the settled claim of the same person a correction (a negative amount)
97	   *  corrects; null when none is named. */
98	  corrects: string | null;
99	}
100	
101	/** What a quick-add made: the person the claim is for (added when the name was not on the sheet)
102	 *  and the draft claim. */
103	export interface QuickAdded {
104	  person: Person;
105	  personAdded: boolean;
106	  claim: Claim;
107	}
108	
109	/** An amount with up to two decimals, 0.00 or more. */
110	export const AMOUNT = /^\d{1,12}(\.\d{1,2})?$/;
111	
112	/** A claim's amount with up to two decimals; a negative one is a correction. */
113	export const CLAIM_AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;
114	
115	/** Whether a claim is a correction: its amount is below 0.00. */
116	export function correction(c: Claim): boolean {
117	  return c.amount.startsWith('-') && Number(c.amount) !== 0;
118	}
119	
120	/** The sum of amounts (two-decimal text), added in cents so no rounding creeps in. */
121	export function sumAmounts(amounts: string[]): string {
122	  const cents = amounts.reduce((sum, a) => sum + Math.round(Number(a) * 100), 0);
123	  return (cents / 100).toFixed(2);
124	}
125	
126	/** Whether a claim is bound by its person's last statement now: it was bound, and it is not
127	 *  pending (a pending claim shows its live figure). */
128	function bound(c: Claim): boolean {
129	  return c.stated && c.status !== 'PENDING';
130	}
131	
132	/** Whether a claim keeps a figure that rates and grades no longer change: settled or bound by a
133	 *  statement. */
134	export function fixed(c: Claim): boolean {
135	  return c.settledDue !== null || (bound(c) && (c.statedDue !== null || c.statedNa));
136	}
137	
138	/** What a claim's late charge follows: the sheet's today and its late percents (a claim takes the
139	 *  one in force on its date); and the sheet's policy date, which decides how its live figures round. */
140	export interface Lateness {
141	  today: string | null;
142	  /** The late percents recorded, each from its from-date, earliest first. */
143	  pcts: DatedValue[];
144	  /** The policy date set (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
145	  policyDate: string | null;
146	}
147	
148	/** Whether a claim's live figures round half up: the date it rounds by is before the policy date
149	 *  in force (the one set, or else the sheet's today); otherwise they round half to even. */
150	export function roundsHalfUp(c: Claim, late: Lateness): boolean {
151	  const policy = late.policyDate ?? late.today;
152	  return policy !== null && c.roundsBy < policy;
153	}
154	
155	/** A claim's due figure: the one fixed when it was settled, or else the one its person's last
156	 *  statement bound it to (n/a when it bound it to n/a), or else its live due at the rate in force on the claim's date for the
157	 *  grade (the person's grade in force on that date), rounded by the policy date, at least the sheet's floor in force on the claim's date; with the late charge on top while it is overdue (a
158	 *  settled claim's figure already holds it). A correction has no floor and no late charge. Null when there is none. */
159	export function claimDue(c: Claim, rates: Rate[], grade: Grade | undefined, floors: DatedValue[], late: Lateness): string | null {
160	  if (c.settledDue !== null) return c.settledDue;
161	  if (bound(c) && c.statedNa) return null;
162	  const live = due(c.amount, grade === undefined ? undefined : pctOn(rates, grade, c.date), roundsHalfUp(c, late));
163	  const floored = live === null || correction(c) ? live : atLeast(live, valueOn(floors, c.date, STARTING_FLOOR));
164	  const figure = (bound(c) ? c.statedDue : null) ?? floored;
165	  return figure === null ? null : sumAmounts([figure, lateCharge(c, figure, late)]);
166	}
167	
168	/** The late charge on an overdue claim: the late percent in force on its date of its figure for every full 30 days it
169	 *  is overdue, rounded like a due; 0.00 when it is not overdue, and on a correction. */
170	export function lateCharge(c: Claim, figure: string, late: Lateness): string {
171	  if (correction(c)) return '0.00';
172	  if (!overdue(c, late.today) || late.today === null) return '0.00';
173	  const days = (Date.parse(late.today) - Date.parse(c.dueBy)) / 86_400_000;
174	  const periods = Math.floor(days / 30);
175	  if (periods <= 0) return '0.00';
