import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade } from './people';
import { Session } from './session';

export interface Rate {
  grade: Grade;
  /** The percent as text with two decimals. */
  pct: string;
  /** The day (yyyy-mm-dd) the rate applies from; null when it applies from the beginning of time. */
  from: string | null;
  /** The last day (yyyy-mm-dd) the rate applies; null when it has no end. */
  to: string | null;
}

/** The percent of a grade's rate in force on a day: the rate with the latest from-date on or
 *  before it, or else the one with no from-date; undefined when the day is before every rate, or
 *  after the to-date of that rate. */
export function pctOn(rates: Rate[], grade: Grade, day: string): string | undefined {
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > day)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  if (best?.to != null && best.to < day) return undefined;
  return best?.pct;
}

/** A percent with up to two decimals, 0.00 or more. */
export const PCT = /^\d{1,5}(\.\d{1,2})?$/;

/** Two-decimal text, which may be negative, as a whole number of hundredths. */
function hundredths(text: string): bigint {
  const negative = text.startsWith('-');
  const [whole, frac = ''] = (negative ? text.slice(1) : text).split('.');
  const n = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  return negative ? -n : n;
}

/** An amount's due at a percent: amount times pct divided by 100, rounded to two decimals half to
 *  even, or half up (away from zero) when `halfUp`, worked in whole numbers so no rounding creeps
 *  in; a negative amount has a negative due. Null when there is no rate. */
export function due(amount: string, pct: string | undefined, halfUp = false): string | null {
  if (pct === undefined) return null;
  const signed = hundredths(amount) * hundredths(pct);
  const exact = signed < 0n ? -signed : signed;
  let cents = exact / 10000n;
  const rest = exact % 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  const text = cents.toString().padStart(3, '0');
  return `${signed < 0n && cents > 0n ? '-' : ''}${text.slice(0, -2)}.${text.slice(-2)}`;
}

/** The larger of two two-decimal figures. */
export function atLeast(figure: string, floor: string): string {
  return hundredths(figure) < hundredths(floor) ? floor : figure;
}

// The rates for each grade on the active sheet.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheetId)));
  }

  /** Set a grade's rate from a day (null: from the beginning of time) through a day (null: no
   *  end), replacing the one the grade had for that from-date. */
  set(grade: Grade, pct: string, from: string | null, to: string | null): Promise<Rate> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheetId)}/${grade}`, { pct, from, to }, { headers: { 'X-User': user } }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import type { Claim } from './claims';
import { Session } from './session';

export type Grade = 'A' | 'B' | 'C';

/** A grade a person was given, from a day (yyyy-mm-dd); null: from the beginning of time. */
export interface GradeFrom {
  grade: Grade;
  from: string | null;
}

/** The grade in force on a day: the one with the latest from-date on or before it, or else the one
 *  with no from-date; grades come earliest first. */
export function gradeOn(grades: GradeFrom[], day: string | null): Grade | undefined {
  let on: Grade | undefined;
  for (const g of grades) {
    if (g.from === null || (day !== null && g.from <= day)) on = g.grade;
  }
  return on;
}

/** A hold on a person from a day (null: from the beginning of time) to a day (null: open-ended),
 *  both included (yyyy-mm-dd). */
export interface Hold {
  from: string | null;
  to: string | null;
}

/** Whether one of the holds covers a day. */
export function heldOn(holds: Hold[], day: string): boolean {
  return holds.some((h) => (h.from === null || h.from <= day) && (h.to === null || day <= h.to));
}

export interface Person {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the person was read. */
  grade: Grade;
  /** Every grade recorded for them, earliest first. */
  grades: GradeFrom[];
  /** Raised each time the person is saved. */
  version: number;
  /** How many statements were taken of them. */
  statementCount: number;
  /** The last statement's due-total as text with two decimals; null when it was n/a or none was taken. */
  statedTotal: string | null;
  /** The day (yyyy-mm-dd) the last statement was taken; null when none was. */
  statementDate: string | null;
  /** Whether they are retired: they are as soon as a retirement day is set, whatever the day. */
  retired: boolean;
  /** The day (yyyy-mm-dd) they are retired from; null when they are not retired. */
  retiredFrom: string | null;
  /** Whether they have any hold, whatever its days. */
  held: boolean;
  /** Their holds, earliest first: their open claims dated within one count in no live total. */
  holds: Hold[];
}

/** A statement just taken: the person as they now show, and their claims (newest first) as it
 *  bound them. */
export interface Taken {
  person: Person;
  claims: Claim[];
}

export interface PersonForm {
  name: string;
  grade: Grade;
  /** The day (yyyy-mm-dd) an edit's grade applies from; null takes the sheet's today. */
  gradeFrom?: string | null;
}

