158	export class PersonClaims {
159	  private readonly api = inject(Claims);
160	
161	  readonly personId = input.required<number>();
162	  /** This person's claims, newest first. */
163	  readonly claims = input.required<Claim[]>();
164	  /** The rates set on the sheet; a claim's due uses its person's grade's rate on the claim's date. */
165	  readonly rates = input.required<Rate[]>();
166	  /** The sheet's floors recorded: the least live due a claim has is the one in force on its date. */
167	  readonly floor = input.required<DatedValue[]>();
168	  /** The person's grades; a claim's due uses the one in force on the claim's date. */
169	  readonly grades = input.required<GradeFrom[]>();
170	  /** The periods on the sheet; a claim belongs to the one whose days contain its date. */
171	  readonly periods = input.required<Period[]>();
172	  /** The sheet's today; a claim is overdue once its due-by is before it. */
173	  readonly today = input.required<string | null>();
174	  /** The sheet's late percents recorded: what an overdue claim gains for every full 30 days it is
175	   *  overdue is the one in force on its date. */
176	  readonly latePct = input.required<DatedValue[]>();
177	  /** The sheet's policy date (null when blank): it decides how a claim's live figures round. */
178	  readonly policyDate = input.required<string | null>();
179	  /** The other people on the sheet, whom a claim can be reassigned to. */
180	  readonly others = input.required<Person[]>();
181	  /** The ids of the claims selected for a bulk action. */
182	  readonly selected = input.required<ReadonlySet<number>>();
183	  /** A claim's checkbox ticked or cleared. */
184	  readonly selectedChange = output<{ id: number; selected: boolean }>();
185	  /** A claim added or saved through the form. */
186	  readonly saved = output<Claim>();
187	
188	  /** The id of the claim whose editor is open, or null when the form adds a claim. */
189	  protected readonly editing = signal<number | null>(null);
190	  protected readonly error = signal('');
191	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
192	  private submitting = false;
193	  /** The refusal of the last action taken on a claim's row, shown on that row. */
194	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
195	  protected readonly form = new FormGroup({
196	    amount: new FormControl('', { nonNullable: true }),
197	    date: new FormControl('', { nonNullable: true }),
198	    note: new FormControl('', { nonNullable: true }),
199	    corrects: new FormControl('', { nonNullable: true }),
200	  });
201	
202	  constructor() {
203	    this.form.valueChanges.subscribe(() => this.error.set(''));
204	  }
205	
206	  protected dueOf(c: Claim): string {
207	    return claimDue(c, this.rates(), gradeOn(this.grades(), c.date), this.floor(),
208	      { today: this.today(), pcts: this.latePct(), policyDate: this.policyDate() }) ?? 'n/a';
209	  }
210	
211	  protected dueByOf(c: Claim): string {
212	    return c.dueBy;
213	  }
214	
215	  protected overdueOf(c: Claim): boolean {
216	    return overdue(c, this.today());
217	  }
218	
219	  protected deferredOf(c: Claim): boolean {
220	    return deferred(c, this.today());
221	  }
222	
223	  /** The name of the period the claim belongs to; empty when it belongs to none. */
224	  protected periodName(c: Claim): string {
225	    return periodOf(this.periods(), c.date)?.name ?? '';
226	  }
227	
228	  protected open(c: Claim): void {
229	    this.claimError.set(null);
230	    if (c.status !== 'DRAFT') {
231	      this.claimError.set({ id: c.id, message: NOT_DRAFT });
232	      return;
233	    }
234	    this.editing.set(c.id);
235	    this.form.setValue({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' },
236	      { emitEvent: false });
237	    this.error.set('');
238	  }
239	
240	  /** Clear the refusal shown on a claim's row once its reject reason is changed. */
241	  protected clearError(c: Claim): void {
242	    if (this.claimError()?.id === c.id) this.claimError.set(null);
243	  }
244	
245	  protected async act(c: Claim, action: ClaimAction, reason?: string): Promise<void> {
246	    this.claimError.set(null);
247	    if (action === 'reject' && (reason ?? '').trim() === '') {
248	      this.claimError.set({ id: c.id, message: refusal(new HttpErrorResponse({ status: 400 }), action) });
249	      return;
250	    }
251	    try {
252	      this.saved.emit(await this.api.act(c.id, action, reason?.trim()));
253	    } catch (e) {
254	      this.claimError.set({
255	        id: c.id,
256	        message: refusal(e, action),
257	      });
258	    }
259	  }
260	
261	  protected async defer(c: Claim, until: string): Promise<void> {
262	    this.claimError.set(null);
263	    if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) {
264	      this.claimError.set({ id: c.id, message: DEFER_DATE });
265	      return;
266	    }
267	    try {
268	      this.saved.emit(await this.api.defer(c.id, until));
269	    } catch (e) {
270	      this.claimError.set({ id: c.id, message: deferRefusal(e) });
271	    }
272	  }
273	
274	  protected async reassign(c: Claim, to: string): Promise<void> {
275	    this.claimError.set(null);
276	    if (to === '') {
277	      this.claimError.set({ id: c.id, message: 'Choose the person to reassign the claim to.' });
278	      return;
279	    }
280	    try {
281	      this.saved.emit(await this.api.reassign(c.id, Number(to)));
282	    } catch (e) {
283	      this.claimError.set({ id: c.id, message: reassignRefusal(e) });
284	    }
285	  }
286	
287	  protected cancel(): void {
288	    this.reset();
289	  }
290	
291	  protected async submit(): Promise<void> {
292	    if (this.submitting) return;
293	    this.error.set('');
294	    this.claimError.set(null);
295	    const { amount, date, note, corrects } = this.form.getRawValue();
296	    if (!CLAIM_AMOUNT.test(amount.trim())) {
297	      this.error.set('Enter an amount with up to two decimals; a negative amount is a correction.');
298	      return;
299	    }
300	    const number = corrects.trim();
301	    if (number.length > 120) {
302	      this.error.set(CORRECTS);
303	      return;
304	    }
305	    const day = date.trim();
306	    if (day !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(day)) {
307	      this.error.set('Enter a date, or leave it blank for the sheet\'s today.');
308	      return;
309	    }
310	    const form = {
311	      amount: amount.trim(), date: day === '' ? null : day, note, corrects: number === '' ? null : number,
312	    };
313	    const id = this.editing();
314	    this.submitting = true;
315	    try {
316	      const claim = id === null ? await this.api.add(this.personId(), form) : await this.api.edit(id, form);
317	      this.saved.emit(claim);
318	      this.reset();
319	    } catch (e) {
320	      if (e instanceof HttpErrorResponse && e.status === 423) this.error.set(CLOSED);
321	      else if (e instanceof HttpErrorResponse && e.status === 422) this.error.set(RETIRED);
322	      else if (e instanceof HttpErrorResponse && e.status === 400 && amount.trim().startsWith('-')) this.error.set(CORRECTS);
323	      else if (id !== null && e instanceof HttpErrorResponse && e.status === 409) {
324	        this.claimError.set({ id, message: NOT_DRAFT });
325	      }
326	      else this.error.set(id === null ? 'The claim could not be added.' : 'The claim could not be saved.');
327	    } finally {
328	      this.submitting = false;
329	    }
330	  }
331	
332	  private reset(): void {
333	    this.editing.set(null);
334	    this.form.reset({ amount: '', date: '', note: '', corrects: '' }, { emitEvent: false });
335	    this.error.set('');
336	  }
337	}
